"""Count-based word vectors: term-document and term-term matrices, dot product vs cosine."""
import numpy as np
plays = ["As You Like It", "Twelfth Night", "Julius Caesar", "Henry V"]
td = {"battle": [1, 0, 7, 13], "good": [114, 80, 62, 89], "fool": [36, 58, 1, 4]}
def cos(a, b): a, b = np.array(a, float), np.array(b, float); return a @ b / (np.linalg.norm(a) * np.linalg.norm(b))
print("Term-document: word vectors are rows, document vectors are columns.")
for w, v in td.items(): print(f"  {w:<7} {v}")
docs = np.array(list(td.values())).T
for i in range(4):
    for j in range(i + 1, 4):
        print(f"  cos({plays[i]}, {plays[j]}) = {cos(docs[i], docs[j]):.3f}")

ctx = ["computer", "data", "result", "pie", "sugar"]
tt = {"cherry": [2, 8, 9, 442, 25], "strawberry": [0, 0, 1, 60, 19], "digital": [1670, 1683, 85, 5, 4], "information": [3325, 3982, 378, 5, 13]}
print("\nTerm-term (context words: " + ", ".join(ctx) + ")")
words = list(tt)
print(f"{'':<12}" + "".join(f"{w:>13}" for w in words))
for a in words:
    print(f"{a:<12}" + "".join(f"{cos(tt[a], tt[b]):13.3f}" for b in words))
print("\nDot products favour long (frequent) vectors:")
for a, b in [("cherry", "strawberry"), ("cherry", "information"), ("digital", "information")]:
    print(f"  dot({a}, {b}) = {np.dot(tt[a], tt[b]):>10,}   cosine = {cos(tt[a], tt[b]):.3f}")
